mapper.select:
select t.machine_id,t.machine_id machineId,t.spec_cd,t.spec_cd specCd,t.status_cd,t.status_cd
statusCd,t.param_id,t.param_id paramId,t.community_id,t.community_id communityId,t.value,ifs.spec_name specName
from instrument_param t
left join instrument_factory_spec ifs on t.spec_cd = ifs.spec_cd and ifs.status_cd = '0'
where 1 =1

    and t.machine_id= #{machineId}


    and t.spec_cd= #{specCd}


    and t.status_cd= #{statusCd}


    and t.param_id= #{paramId}


    and t.community_id= #{communityId}


    and t.value= #{value}

order by t.create_time desc

    limit #{page}, #{row}

